=== eng-2194
{
  "name": "eng-2194",
  "title": "Node summoning menu \"Only\" button stretches across filter row",
  "baseline": "dg-baseline@1",
  "target": {
    "slot": "3",
    "pr": 1485,
    "dist": "/mnt/data/projects/dg-test-eng-2194",
    "viewport": {
      "width": 1280,
      "height": 720
    }
  },
  "needs": [
    "supabase",
    "embed-stub"
  ],
  "prepare": [
    {
      "id": "database-session",
      "why": "the extension has a proof database session for this graph; the proof database runs without edge functions, so this signs in the way create-space would",
      "phase": "before-load",
      "check": {
        "js": "proof.supabase.signedIn()"
      },
      "apply": {
        "js": "proof.supabase.signIn({ serviceKey: '{{env.SUPABASE_SERVICE_ROLE_KEY}}', publishableKey: '{{env.SUPABASE_PUBLISHABLE_KEY}}' })"
      },
      "settleMs": 1000
    },
    {
      "id": "scratch-page",
      "why": "an empty page to type the node search trigger on",
      "phase": "in-session",
      "apply": {
        "js": "proof.page.recreate('PK node search scratch', [''])"
      }
    }
  ],
  "cases": [
    {
      "id": "only-sizes-to-label",
      "title": "Each Only button sizes to its label at the right edge of its row",
      "proves": "Done When 1: The Only button stays compact and right-aligned when a node-type row is hovered, with no stretching or layout shift.",
      "caption": "In the node summoning menu's type filter, the Only button now fits its label and sits at the right edge of each row, instead of taking half the row.",
      "steps": [
        {
          "use": "node-search-menu.open",
          "with": {
            "page": "PK node search scratch"
          },
          "why": "open the node summoning menu"
        },
        {
          "do": {
            "click": ".discourse-node-search-menu button[title=\"Filter by type\"]"
          },
          "why": "open the type filter"
        },
        {
          "do": {
            "wait_for": ".discourse-node-search-menu .max-h-48 .bp3-menu-item"
          },
          "why": "wait for the type rows"
        },
        {
          "do": {
            "hover": ".discourse-node-search-menu .max-h-48 .bp3-menu-item:has-text(\"Claim\")"
          },
          "why": "hover Claim so its Only button shows"
        },
        {
          "do": {
            "pause": 1.5
          },
          "why": "hold on the row"
        }
      ],
      "expect": {
        "js": "(() => { const rows = Array.from(document.querySelectorAll('.discourse-node-search-menu .max-h-48 .bp3-menu-item')).filter(proof.visible); proof.assert(rows.length >= 4, 'Expected at least 4 type rows, found ' + rows.length + '.'); for (const row of rows) { const only = proof.byText('button', 'Only', row); proof.assert(only, 'A type row has no Only button.'); const box = proof.rect(only); const style = getComputedStyle(row); const contentRight = proof.rect(row).right - parseFloat(style.paddingRight) - parseFloat(style.borderRightWidth); const edge = contentRight - box.right; proof.assert(box.width < 100, 'The Only button is ' + Math.round(box.width) + 'px wide; it should fit its label.'); proof.assert(Math.abs(edge) <= 2, 'The Only button sits ' + Math.round(edge) + 'px inside the row content edge.'); } })()"
      }
    },
    {
      "id": "only-filters",
      "title": "Only on Claim leaves just the Claim results",
      "caption": "Clicking Only still does its job: the filter closes and only the Claim results are left.",
      "steps": [
        {
          "do": {
            "click": ".discourse-node-search-menu .max-h-48 .bp3-menu-item:has-text(\"Claim\") button:has-text(\"Only\")"
          },
          "why": "keep only Claim"
        },
        {
          "do": {
            "pause": 1.5
          },
          "why": "hold on the filtered results"
        }
      ],
      "expect": {
        "js": "proof.waitFor(() => { const headers = Array.from(document.querySelectorAll('.discourse-node-search-menu .h-64 > div > .border-b')).filter(proof.visible).map((el) => el.innerText.trim()); return headers.length === 1 && headers[0] === 'Claim' && !document.querySelector('.discourse-node-search-menu .max-h-48'); }, { what: 'only the Claim results, with the filter closed' })"
      }
    }
  ]
}

=== eng-2267
{
  "name": "eng-2267",
  "title": "Native-Obsidian styling pass for advanced node search",
  "target": {
    "app": "obsidian",
    "cdp": "http://127.0.0.1:9223",
    "vault": "/home/sid/Sid-Obsidian-test",
    "pr": 1484,
    "dist": "/mnt/data/projects/dg-test-eng-2267-obsidian",
    "viewport": {
      "width": 1280,
      "height": 720
    }
  },
  "needs": [
    "supabase",
    "embed-stub"
  ],
  "prepare": [
    {
      "id": "quiet",
      "why": "no modal is open",
      "phase": "in-session",
      "apply": {
        "js": "proof.obsidian.closeModals()"
      }
    }
  ],
  "cases": [
    {
      "id": "toolbar-sizes",
      "title": "The search toolbar uses Obsidian's UI font size",
      "caption": "Node search's toolbar now takes its sizes from Obsidian's own variables, so the query field and its triggers match Obsidian's menus.",
      "steps": [
        {
          "do": {
            "command_palette": "Open node search"
          },
          "why": "open node search the way a user would"
        },
        {
          "do": {
            "wait_for": ".modal button[title=\"Filter by type\"]"
          },
          "why": "wait for the toolbar"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the toolbar"
        }
      ],
      "expect": {
        "js": "(() => { const input = document.querySelector('.modal input'); proof.assert(input, 'No search field in the modal.'); const want = getComputedStyle(document.body).getPropertyValue('--font-ui-small').trim(); proof.assert(want && getComputedStyle(input).fontSize === want, 'The search field is ' + getComputedStyle(input).fontSize + ', not --font-ui-small (' + want + ').'); })()"
      }
    },
    {
      "id": "filter-panel-border",
      "title": "The filter panel draws its border and dividers",
      "caption": "The filter panel now draws its border and dividers, which never rendered before.",
      "steps": [
        {
          "do": {
            "click": ".modal button[title=\"Filter by type\"]"
          },
          "why": "open the type filter"
        },
        {
          "do": {
            "wait_for": ".modal div.absolute.top-full"
          },
          "why": "wait for the panel"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the panel"
        }
      ],
      "expect": {
        "js": "(() => { const panel = document.querySelector('.modal div.absolute.top-full'); proof.assert(panel, 'The filter panel is not open.'); const style = getComputedStyle(panel); proof.assert(style.borderTopStyle === 'solid' && parseFloat(style.borderTopWidth) > 0, 'The filter panel has no border.'); const divider = panel.querySelector('.border-b'); proof.assert(!divider || getComputedStyle(divider).borderBottomStyle === 'solid', 'A filter panel divider has no border.'); })()"
      }
    },
    {
      "id": "sort-panel-border",
      "title": "The sort panel matches Obsidian's menus too",
      "caption": "The sort panel gets the same border and spacing.",
      "steps": [
        {
          "do": {
            "click": ".modal button[title=\"Filter by type\"]"
          },
          "why": "close the type filter"
        },
        {
          "do": {
            "click": ".modal button[title^=\"Sort by\"]"
          },
          "why": "open the sort menu"
        },
        {
          "do": {
            "wait_for": ".modal div.absolute.top-full"
          },
          "why": "wait for the panel"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the panel"
        }
      ],
      "expect": {
        "js": "(() => { const panel = document.querySelector('.modal div.absolute.top-full'); proof.assert(panel, 'The sort panel is not open.'); const style = getComputedStyle(panel); proof.assert(style.borderTopStyle === 'solid' && parseFloat(style.borderTopWidth) > 0, 'The sort panel has no border.'); })()"
      }
    }
  ]
}

=== eng-2296
{
  "name": "eng-2296",
  "title": "Simplify the Roam import dialog and import feedback",
  "baseline": "dg-baseline@1",
  "target": {
    "slot": "3",
    "pr": 1479,
    "dist": "/mnt/data/projects/dg-test-eng-2296",
    "viewport": {
      "width": 1280,
      "height": 720
    }
  },
  "needs": [
    "supabase",
    "embed-stub"
  ],
  "prepare": [
    {
      "id": "shared-claims",
      "why": "the Obsidian test vault published three claims to the eng-2329-demo group",
      "phase": "outside",
      "apply": {
        "publish": {
          "space": 106039,
          "author": 106041,
          "group": "eng-2329-demo",
          "types": [
            {
              "id": "node_pk-2296-claim",
              "label": "PK Import Claim",
              "format": "PKC - {content}"
            }
          ],
          "nodes": [
            {
              "id": "pk-2296-claim-1",
              "type": "node_pk-2296-claim",
              "title": "Daylight exposure resets the circadian clock",
              "body": "Morning light shifts melatonin onset earlier.\n"
            },
            {
              "id": "pk-2296-claim-2",
              "type": "node_pk-2296-claim",
              "title": "Caffeine after noon delays sleep onset",
              "body": "Half-life is five to six hours.\n"
            },
            {
              "id": "pk-2296-claim-3",
              "type": "node_pk-2296-claim",
              "title": "Cool bedrooms improve deep sleep",
              "body": "Around 18 degrees Celsius works best.\n"
            }
          ]
        }
      }
    },
    {
      "id": "no-earlier-import",
      "why": "none of the three claims, nor their type, was imported into this graph before",
      "phase": "before-load",
      "check": {
        "js": "![\"discourse-graph/nodes/PK Import Claim\", \"PKC - Daylight exposure resets the circadian clock\", \"PKC - Caffeine after noon delays sleep onset\", \"PKC - Cool bedrooms improve deep sleep\"].some((title) => proof.page.exists(title))"
      },
      "apply": {
        "js": "proof.page.remove([\"discourse-graph/nodes/PK Import Claim\", \"PKC - Daylight exposure resets the circadian clock\", \"PKC - Caffeine after noon delays sleep onset\", \"PKC - Cool bedrooms improve deep sleep\"])"
      }
    },
    {
      "id": "database-session",
      "why": "the extension has a proof database session for this graph; the proof database runs without edge functions, so this signs in the way create-space would",
      "phase": "before-load",
      "check": {
        "js": "proof.supabase.signedIn()"
      },
      "apply": {
        "js": "proof.supabase.signIn({ serviceKey: '{{env.SUPABASE_SERVICE_ROLE_KEY}}', publishableKey: '{{env.SUPABASE_PUBLISHABLE_KEY}}' })"
      },
      "settleMs": 1000
    }
  ],
  "cases": [
    {
      "id": "result-lists-links",
      "title": "The import result links every imported node",
      "caption": "Import two shared claims. The result now lists each imported node as a link, not only the ones with warnings.",
      "steps": [
        {
          "use": "discover.open",
          "why": "open import the way a user would"
        },
        {
          "do": {
            "wait_for": ".bp3-dialog tbody tr:has-text(\"Daylight exposure resets the circadian clock\")"
          },
          "why": "wait for the shared node's row"
        },
        {
          "do": {
            "click": ".bp3-dialog tbody tr:has-text(\"Daylight exposure resets the circadian clock\") label.bp3-checkbox"
          },
          "why": "select it"
        },
        {
          "do": {
            "click": ".bp3-dialog tbody tr:has-text(\"Caffeine after noon delays sleep onset\") label.bp3-checkbox"
          },
          "why": "select a second claim"
        },
        {
          "do": {
            "click": ".bp3-dialog button:has-text(\"Import selected (2)\")"
          },
          "why": "import the selection"
        },
        {
          "do": {
            "wait_for": ".bp3-dialog .bp3-callout:has-text(\"imported\")"
          },
          "why": "wait for the import result"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the result"
        }
      ],
      "expect": {
        "js": "proof.waitFor(() => { const callout = proof.byText('.bp3-dialog .bp3-callout', 'imported'); if (!callout) return false; const links = Array.from(callout.querySelectorAll('li a')).map((link) => link.innerText); return callout.innerText.includes('2 imported') && links.some((text) => text.includes('Daylight exposure')) && links.some((text) => text.includes('Caffeine after noon')); }, { what: 'a result listing both imported claims as links', timeout: 20000 })"
      }
    },
    {
      "id": "imported-rows-leave-the-table",
      "title": "Imported nodes leave the table",
      "caption": "Imported nodes leave the table, as in Obsidian's import, so only the claim still to import is left.",
      "steps": [
        {
          "do": {
            "pause": 1
          },
          "why": "look at the table under the result"
        }
      ],
      "expect": {
        "js": "proof.waitFor(() => { const rows = Array.from(document.querySelectorAll('.bp3-dialog tbody tr')).map((row) => row.innerText); return rows.some((text) => text.includes('Cool bedrooms')) && !rows.some((text) => text.includes('Daylight exposure') || text.includes('Caffeine after noon')); }, { what: 'only the unimported claim in the table' })"
      }
    },
    {
      "id": "link-opens-the-page",
      "title": "Clicking a result opens the page and closes the dialog",
      "caption": "Clicking a result opens that page and closes the dialog.",
      "steps": [
        {
          "do": {
            "click": ".bp3-dialog .bp3-callout li a:has-text(\"Daylight exposure\")"
          },
          "why": "open the imported claim"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the page"
        }
      ],
      "expect": {
        "js": "proof.waitFor(() => !proof.dialogs().length && Array.from(document.querySelectorAll('.rm-title-display')).some((title) => proof.visible(title) && title.innerText.includes('Daylight exposure resets the circadian clock')), { what: 'the imported page open with the dialog closed' })"
      }
    },
    {
      "id": "reopen-hides-imported",
      "title": "Reopening import still hides what's already imported",
      "caption": "Open import again: the two imported claims stay hidden. A newer version comes in through Refresh instead.",
      "steps": [
        {
          "use": "discover.open",
          "why": "open import again"
        },
        {
          "do": {
            "wait_for": ".bp3-dialog tbody tr:has-text(\"Cool bedrooms\")"
          },
          "why": "wait for the table"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the table"
        }
      ],
      "expect": {
        "js": "(() => { const rows = Array.from(document.querySelectorAll('.bp3-dialog tbody tr')).map((row) => row.innerText); proof.assert(!rows.some((text) => text.includes('Daylight exposure') || text.includes('Caffeine after noon')), 'An imported claim is still in the table.'); })()"
      }
    }
  ]
}

=== eng-2195
{
  "name": "eng-2195",
  "title": "Normalize imported node type formats for Obsidian filenames",
  "target": {
    "app": "obsidian",
    "cdp": "http://127.0.0.1:9223",
    "vault": "/home/sid/Sid-Obsidian-test",
    "pr": 1507,
    "dist": "/mnt/data/projects/dg-test-eng-2195-obsidian",
    "viewport": {
      "width": 1280,
      "height": 720
    }
  },
  "needs": [
    "supabase",
    "embed-stub"
  ],
  "prepare": [
    {
      "id": "roam-bracket-format",
      "why": "the dev graph published a PK Note node type with Roam's bracketed format [[PKN]] - {content}, and one node, to the eng-2329-demo group",
      "phase": "outside",
      "apply": {
        "publish": {
          "space": 66566,
          "author": 3,
          "group": "eng-2329-demo",
          "types": [
            {
              "id": "pk-2195-note",
              "label": "PK Note",
              "format": "[[PKN]] - {content}"
            }
          ],
          "nodes": [
            {
              "id": "pk-2195-roam-note",
              "type": "pk-2195-note",
              "title": "Sleep improves memory",
              "body": "- Shared from Roam."
            }
          ]
        }
      }
    },
    {
      "id": "no-earlier-import",
      "why": "the vault has no PK Note type or note from an earlier import",
      "phase": "in-session",
      "apply": {
        "js": "(async () => { await proof.obsidian.closeModals(); await proof.obsidian.removeFiles(proof.obsidian.importedFiles(['pk-2195-roam-note'])); await proof.obsidian.removeNodeTypes(['PK Note']); proof.obsidian.clearNotices(); })()"
      }
    }
  ],
  "cases": [
    {
      "id": "bracket-format-normalized",
      "title": "A Roam format with brackets becomes a valid Obsidian format",
      "caption": "Roam formats wrap the tag in double brackets, which Obsidian file names can't hold. Importing a Roam node type now stores its format as PKN, dash, content.",
      "steps": [
        {
          "do": {
            "command_palette": "Import nodes from another space"
          },
          "why": "open import the way a user would"
        },
        {
          "do": {
            "wait_for": ".modal h3:has-text(\"Select nodes to import\")"
          },
          "why": "wait for the shared nodes to load"
        },
        {
          "do": {
            "click": ".modal div.items-start:has-text(\"Sleep improves memory\") input[type=\"checkbox\"]"
          },
          "why": "select the shared node"
        },
        {
          "do": {
            "click": ".modal button:has-text(\"Next (1)\")"
          },
          "why": "go to the preview"
        },
        {
          "do": {
            "wait_for": ".modal button:has-text(\"Confirm Import\")"
          },
          "why": "wait for the preview"
        },
        {
          "do": {
            "click": ".modal button:has-text(\"Confirm Import\")"
          },
          "why": "import it"
        },
        {
          "do": {
            "js": "proof.waitFor(() => /Successfully imported|Import completed/.test(proof.obsidian.notices()), { what: 'the import to finish', timeout: 30000 })"
          },
          "why": "wait for the import notice"
        },
        {
          "do": {
            "pause": 1.5
          },
          "why": "hold on the result"
        }
      ],
      "expect": {
        "js": "proof.waitFor(() => { const type = proof.obsidian.nodeType('PK Note'); return type && type.format === 'PKN - {content}'; }, { what: 'PK Note with the format PKN - {content}', timeout: 20000 })"
      }
    },
    {
      "id": "file-named-from-format",
      "title": "The imported note's file is named from that format",
      "caption": "So the imported note decorates as a normal file name: PKN, dash, Sleep improves memory.",
      "steps": [
        {
          "do": {
            "js": "proof.obsidian.open(proof.obsidian.importedFiles(['pk-2195-roam-note'])[0].path)"
          },
          "why": "open the imported note"
        },
        {
          "do": {
            "pause": 2
          },
          "why": "hold on the note"
        }
      ],
      "expect": {
        "js": "proof.assert(window.app.workspace.getActiveFile().basename === 'PKN - Sleep improves memory', 'The imported note is named ' + window.app.workspace.getActiveFile().basename + '.')"
      }
    }
  ]
}
