import { spawn } from "node:child_process";
import fsSync from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { CHAPTERS_PREFIX, clock, type Chapter } from "../recorder/chapters";
import type { Coverage } from "./donewhen";
import type { Action, Scene, Storyboard } from "../recorder/recordDemo";
import { assertCase, inSessionSteps, smokeSteps } from "./fixtures";
import { HELPERS_INIT_SCRIPT } from "./helpers";
import { loadRecipes, makeExpander, type RecipeBook } from "./recipes";
import {
  BASELINE_DIR,
  actionJs,
  decisionOf,
  isRunnable,
  kitScopeLines,
  validateBaseline,
  validateKit,
  type Baseline,
  type Kit,
  type Step,
} from "./kit";
import { fillDeep, type TemplateContext } from "./template";

const RECORD_DEMO = path.resolve(__dirname, "../recorder/recordDemo.ts");
const RECORD_OBSIDIAN = path.resolve(__dirname, "../recorder/recordObsidian.ts");

// The running Obsidian loaded whatever plugin was installed when it started,
// so an Obsidian take reloads the plugin from disk before anything else. A
// kit that uses the database signs the vault in first, since the local
// create-space edge function is down.
const RELOAD_OBSIDIAN_PLUGIN: Action = { js: "proof.obsidian.reloadPlugin()" };
const SIGN_IN_OBSIDIAN: Action = {
  js: "proof.obsidian.signIn({ serviceKey: '{{env.SUPABASE_SERVICE_ROLE_KEY}}', publishableKey: '{{env.SUPABASE_PUBLISHABLE_KEY}}' })",
};

export const obsidianSetup = (kit: Kit): Action[] =>
  kit.target?.app !== "obsidian"
    ? []
    : (kit.needs ?? []).includes("supabase")
      ? [SIGN_IN_OBSIDIAN, RELOAD_OBSIDIAN_PLUGIN]
      : [RELOAD_OBSIDIAN_PLUGIN];

export type TakeReadiness = { blockers: string[]; unverified: string[] };

// A take runs with nobody at the screen, so it can't do what needs you: work
// out steps from an intent, or run js you haven't allowed. Cases checked only
// by eye still go in; the video is the evidence for them.
export const takeReadiness = (kit: Kit): TakeReadiness => {
  const blockers: string[] = [];
  const unverified: string[] = [];
  const proposed = kit.cases.filter((testCase) => decisionOf(testCase) === "proposed");
  if (proposed.length) {
    blockers.push(
      `${proposed.length} proposed case${proposed.length === 1 ? " waits" : "s wait"} for a decision (${proposed.map((testCase) => testCase.id).join(", ")}). Approve or reject them: qa.ts decide --kit <kit>.`,
    );
  }
  if (!kit.cases.some(isRunnable)) blockers.push("No case is approved, so there's nothing to record.");
  for (const testCase of kit.cases.filter(isRunnable)) {
    if (testCase.steps.length === 0 && testCase.intent) {
      blockers.push(
        `${testCase.id} "${testCase.title}" has no steps yet. Rehearse it live once, or write its steps.`,
      );
    }
    for (const step of testCase.steps) {
      if (
        step.do !== undefined &&
        actionJs(step.do) !== null &&
        (step.source ?? "kit") !== "kit" &&
        !step.approved
      ) {
        blockers.push(
          `${testCase.id} step ${step.id} is js from ${step.source === "you" ? "your instructions" : "the brain"} that you haven't allowed. Allow it in a live rehearsal first.`,
        );
      }
    }
    if (!testCase.expect?.js && testCase.expect?.text) {
      unverified.push(
        `${testCase.id} "${testCase.title}": ${testCase.expect.text}`,
      );
    }
  }
  return { blockers, unverified };
};

export const buildTakeStoryboard = ({
  kit,
  baseline,
  sessionDir,
  distDir,
  context,
  recipes,
}: {
  kit: Kit;
  baseline: Baseline | null;
  sessionDir: string;
  distDir: string | null;
  context: TemplateContext;
  recipes: RecipeBook;
}): Storyboard => {
  const expand = makeExpander(recipes);
  const actionsOf = (step: Step): Action[] =>
    expand(step).map((action) => fillDeep(action, context));
  const fixtures = [...(baseline?.prepare ?? []), ...(kit.prepare ?? [])];
  const setup = [
    // As in runPageFixtures: make sure window.proof exists before setup uses it.
    { js: HELPERS_INIT_SCRIPT },
    ...obsidianSetup(kit).map((action) => fillDeep(action, context)),
    ...[...inSessionSteps(fixtures), ...smokeSteps(baseline?.smoke ?? [])].flatMap(actionsOf),
  ];
  const scenes: Scene[] = kit.cases.filter(isRunnable).map((testCase) => {
    const actions: Action[] = testCase.steps.flatMap(actionsOf);
    if (testCase.expect?.js) {
      actions.push(
        fillDeep(
          assertCase(testCase.expect.js, `Case ${testCase.id} failed`),
          context,
        ),
      );
    }
