import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";
import { CONNECTING_FLAGS, connectingFlagsAfter } from "../core/database";
import { loadBaseline, loadKit, type Step } from "../kit";
import { loadRecipes, makeExpander } from "../recipes";
import { takeReadiness } from "../take";

const KITS_DIR = path.join(__dirname, "..", "kits");

test("every shipped kit and the baseline validate, and their recipe steps expand", async () => {
  const expand = makeExpander(loadRecipes());
  const baseline = await loadBaseline("dg-baseline@1");
  const stepsOf = (cases: { steps: Step[] }[], fixtures: { apply: object }[]): Step[] => [
    ...cases.flatMap((testCase) => testCase.steps),
    ...fixtures.flatMap((fixture) =>
      "steps" in fixture.apply ? (fixture.apply.steps as Step[]) : [],
    ),
  ];
  for (const step of stepsOf(baseline.smoke, baseline.prepare)) {
    assert.ok(expand(step).length > 0, `baseline ${step.id}`);
  }
  const files = fs.readdirSync(KITS_DIR).filter((file) => file.endsWith(".json"));
  assert.ok(files.length > 0);
  for (const file of files) {
    const kit = await loadKit(path.join(KITS_DIR, file));
    if (kit.baseline) await loadBaseline(kit.baseline);
    for (const step of stepsOf(kit.cases, kit.prepare ?? [])) {
      assert.ok(expand(step).length > 0, `${file} ${step.id}`);
    }
  }
});

test("every shipped kit is ready for an unattended take", async () => {
  for (const file of fs.readdirSync(KITS_DIR).filter((name) => /^eng-[\w-]+\.json$/.test(name))) {
    const kit = await loadKit(path.join(KITS_DIR, file));
    assert.deepEqual(takeReadiness(kit).blockers, [], file);
  }
});

test("dg-baseline@2 leaves DG off any database, so a UI-only kit runs on a PR's CI build", async () => {
  const setupJs = async (ref: string): Promise<string[]> =>
    (await loadBaseline(ref)).prepare.flatMap((fixture) => (fixture.phase === "before-load" && "js" in fixture.apply ? [fixture.apply.js] : []));
  // Even when an earlier kit left sync and sharing on in the graph.
  assert.deepEqual(connectingFlagsAfter(CONNECTING_FLAGS, await setupJs("dg-baseline@2")), []);
  assert.deepEqual(connectingFlagsAfter([], await setupJs("dg-baseline@1")).sort(), [...CONNECTING_FLAGS].sort());
});
