const push = async (options: Options): Promise<void> => {
  if (typeof options.kit !== "string") throw new Error("push needs --kit <file>.");
  const kit = await loadKit(path.resolve(options.kit));
  if (typeof options.pr === "string") kit.target = { ...(kit.target ?? {}), pr: Number(options.pr) };
  const { session, graphUrl } = await open(options);
  try {
    const page = session.page;
    if (!fs.existsSync(BUNDLE)) await buildRunner();
    await ensureRunner(page);
    const written = await page.evaluate(
      async ({ raw, build, title, replace }) =>
        (window as unknown as { proofRunner: { writeKit(kit: unknown, options: unknown): Promise<{ pageUid: string; title: string }> } }).proofRunner.writeKit(raw, {
          build,
          title,
          replace,
        }),
      {
        raw: kit,
        build: typeof options.build === "string" ? options.build : null,
        title: typeof options.title === "string" ? options.title : undefined,
        replace: options.replace === true,
      },
    );
    await waitForSync(page);
    log(`Wrote ${kit.name} to "${written.title}".`);
    console.log(`${graphUrl}/page/${written.pageUid}`);
  } finally {
    if (options["keep-open"] !== true) await session.close();
  }
};

