// Roam saves to its server a few seconds after a write, so closing the
// browser right after one loses it. Wait for the sync icon to settle on
// synced: briefly once a save was seen, longer when none has started yet.
const waitForSync = async (page: Page, timeoutMs = 120_000): Promise<void> => {
  const started = Date.now();
  let syncedSince = 0;
  let sawSaving = false;
  while (Date.now() - started < timeoutMs) {
    const state = await page.evaluate(() => document.querySelector(".rm-sync__icon")?.className ?? "");
    if (state.includes("rm-sync--synced")) {
      syncedSince = syncedSince || Date.now();
      if (Date.now() - syncedSince > (sawSaving ? 2000 : 10_000)) return;
    } else {
      syncedSince = 0;
      sawSaving = sawSaving || state.includes("rm-sync--saving");
    }
    await sleep(250);
  }
  throw new Error("Roam didn't finish saving in time; leave the window open until its sync icon settles.");
};

const hasRunner = (page: Page): Promise<boolean> =>
  page.evaluate(() => Boolean((window as unknown as { proofRunner?: unknown }).proofRunner));

// The runner as this account has it (developer extension or roam/js);
// otherwise this session imports the built extension.js itself and starts it
// the way the roam/js loader would, without an extensionAPI.
const ensureRunner = async (page: Page, waitMs = 8000): Promise<"installed" | "injected"> => {
  const deadline = Date.now() + waitMs;
  while (Date.now() < deadline) {
    if (await hasRunner(page)) return "installed";
    await sleep(250);
  }

