6	// The run panel inside a {{proof}} block: the live HUD's layout (what the kit
7	// proves, every case with its steps, what's waiting on you, a feed, the
8	// controls) moved into the page, where it calls the machine directly instead
9	// of through a Playwright binding. Its own buttons and text sit in a shadow
10	// root, so kit selectors and proof.byText never match them. The cases are
11	// the page's own blocks, rendered by Roam into the light DOM and slotted in:
12	// editing a step in the panel edits the page, and the run's state shows on
13	// the blocks themselves (the runner's stylesheet marks them by uid).
14	
15	// Roam renders a block, live and editable, into any element, and takes it
16	// down again. Tests pass a stand-in.
17	export type BlockRenderer = {
18	  render(uid: string, el: HTMLElement): Promise<unknown> | void;
19	  unmount(el: HTMLElement): void;
20	};
21	
22	const roamBlocks: BlockRenderer = {
23	  render: (uid, el) => roam().ui.components.renderBlock({ uid, el }),
24	  unmount: (el) => roam().ui.components.unmountNode({ el }),
25	};
