322	    } else if (action === "toggle") {
323	      request = { kind: "command", cmd: state?.paused ? "resume" : "pause" };
324	    } else if (action === "slower" || action === "faster") {
325	      const current = state ? state.speed : 1;
326	      const index = SPEEDS.findIndex((value) => value >= current);
327	      const at = index < 0 ? SPEEDS.length - 1 : index;
328	      const next = action === "faster" ? Math.min(SPEEDS.length - 1, at + 1) : Math.max(0, at - 1);
