335	        this.stopArmed = 0;
336	        request = { kind: "command", cmd: "stop" };
337	      } else {
338	        this.stopArmed = Date.now() + 3000;
339	        this.repaint();
340	        setTimeout(() => this.repaint(), 3100);
341	        return;
342	      }
343	    } else {
344	      request = { kind: "command", cmd: action, args };
345	    }
