import assert from "node:assert/strict";
import test from "node:test";
import type { Browser, Page } from "playwright";
import { defaultChromium } from "../../../discourse-graph/apps/roam/scripts/playwright/roamSession";
import { bundleForPage } from "../roam/build";

// The runner's in-page parts in a blank page: the Playwright-style selector
// engine, the executor's actions, and the panel.

const ENTRY = `
import { queryAll } from "./selector";
import { makePageExecutor } from "./executor";
import { ProofPanel } from "./panel";
import { registerAgentTools } from "./agent-tools";
const label = (element) => element.id || (element.textContent || "").trim();
const actions = [];
const executor = makePageExecutor({
  timeout: 700,
  render: () => undefined,
  palette: async (name) => {
    if (name !== "DG: Open Node Search") return false;
    window.__palette = name;
    return true;
  },
  fill: (value) => value,
  note: (text) => actions.push(text),
});
const tools = {};
registerAgentTools(
  { ai: { addTool: (tool) => { tools[tool.name] = tool; } } },
  {
    runFor: async (page) => { throw new Error("No {{proof}} block on " + (page || "the open page") + "."); },
    seen: () => { window.__seen = (window.__seen || 0) + 1; },
  },
);
window.__tools = tools;
window.__t = {
  q: (selector) => queryAll(selector).map(label),
  run: (action) => executor.run(action),
  check: (js) => executor.check(js),
  snapshot: () => executor.snapshot(),
  panel: () => {
    const host = document.createElement("div");
    document.body.append(host);
    const calls = [];
    // Roam's renderBlock, standing in: a block container per case with its
    // step blocks under it, in the shape Roam renders.
    const rendered = [];
    const unmounted = [];
    const steps = { caseAAAAA: ["stepA1AAA", "stepA2AAA"], caseBBBBB: [], caseCCCCC: [] };
    const block = (uid, children) =>
      '<div class="roam-block-container"><div class="rm-block-main"><div class="rm-block__input" id="block-input-w-' + uid + '">' + uid +
      '</div></div><div class="rm-block-children">' + children + "</div></div>";
    const renderer = {
      render: (uid, el) => {
        rendered.push(uid);
        el.innerHTML = block(uid, (steps[uid] || []).map((step) => block(step, "")).join(""));
      },
      unmount: (el) => {
        unmounted.push(el.querySelector(".rm-block__input")?.id);
        el.replaceChildren();
