test("covered or scrolled away, the panel's status and controls float in a bar until the run ends", async () => {
  await withPage(async (page) => {
    await panelPage(page);
    const bar = () =>
      page.evaluate(() => {
        const host = document.querySelector<HTMLElement>(".proof-runner-bar");
        if (!host || host.hidden) return null;
        const root = host.shadowRoot as ShadowRoot;
        return {
          badge: root.querySelector(".badge")?.textContent,
          now: root.querySelector(".now")?.textContent,
          buttons: Array.from(root.querySelectorAll(".controls button")).map((button) => button.textContent),
        };
      });
    // The panel in plain view: no bar.
    await page.evaluate(() => {
      const w = window as unknown as PanelHarness;
      w.__panel.host.style.cssText = "position: fixed; top: 0; left: 0; width: 520px; z-index: 5; background: #fff;";
      w.__panel.panel.update(w.__view({}));
    });
    assert.equal(await bar(), null);

    // A dialog's overlay over it: the bar comes up with the status in words.
    await page.evaluate(() => {
      const cover = document.getElementById("cover") as HTMLElement;
      cover.style.display = "block";
      cover.style.zIndex = "20";
    });
    await page.waitForFunction(() => Boolean(document.querySelector(".proof-runner-bar:not([hidden])")));
    assert.deepEqual(await bar(), {
      badge: "running",
      now: 'Running case 1/3, "Discover warns", step 2/2: "look".',
      buttons: ["Pause", "Next", "−", "+", "Mode: auto", "✓ Pass", "✗ Fail", "Restart", "Stop"],
    });

    // Step mode says what Next does; Restart, pressed twice, asks the runner to start over.
    const calls = await page.evaluate(async () => {
      const w = window as unknown as PanelHarness;
      w.__panel.panel.update(w.__view({ phase: "waiting-next", mode: "step", executing: false }));
      const root = (document.querySelector(".proof-runner-bar") as HTMLElement).shadowRoot as ShadowRoot;
      const press = async (label: string) => {
        Array.from(root.querySelectorAll("button")).find((button) => button.textContent === label)?.click();
        await new Promise((resolve) => setTimeout(resolve, 50));
      };
      await press("Restart");
      await press("Restart?");
      return w.__panel.calls;
    });
    assert.deepEqual(calls, [{ kind: "restart" }]);
    assert.equal(
      (await bar())?.now,
      'Step mode stops before every step. Press Next to run "look" in case 1/3, "Discover warns", or switch Mode to auto to play on.',
    );

    // The run ends: the bar goes.
    await page.evaluate(() => {
      const w = window as unknown as PanelHarness;
      w.__panel.panel.update(w.__view({ phase: "done" }));
    });
    assert.equal(await page.evaluate(() => document.querySelector(".proof-runner-bar")), null);
  });
});

